#!/usr/bin/env python3
"""Build manuscript-only assets and a claim ledger; never modify experiment data."""
from pathlib import Path
import csv, json, hashlib, subprocess, statistics
ROOT=Path(__file__).resolve().parents[4]
HERE=Path(__file__).resolve().parents[1]
EVID=HERE.parent/'evidence'
BASE='62d1c134b096882c37ce58c1d0ac140236acd9c3'
def read(p): return json.loads((ROOT/p).read_text(encoding='utf-8-sig'))
def rows(p): return list(csv.DictReader((ROOT/p).open(encoding='utf-8-sig')))
def write(p,t): (HERE/p).write_text(t,encoding='utf-8')
def sha(p): return hashlib.sha256((ROOT/p).read_bytes()).hexdigest()
def commit(p): return subprocess.check_output(['git','log','-1','--format=%H',BASE,'--',p],cwd=ROOT,text=True).strip()
mac={}; ledger=[]
def record(id,platform,claim,values,estimator,correctness,cls,report,analysis,script,archive,caveat):
 sources=list(dict.fromkeys([report,analysis,script,archive]))
 for p in sources:
  if not (ROOT/p).is_file(): raise FileNotFoundError(p)
 ledger.append(dict(id=id,platform=platform,manuscript_claim=claim,exact_value=values,statistical_estimator=estimator,correctness_status=correctness,evidence_class=cls,source_report=report,analysis_file=analysis,script=script,archive=archive,source_commit={p:commit(p) for p in sources},sha256={p:sha(p) for p in sources},caveat=caveat))
def val(name,value,digits=None): mac[name]=str(value) if digits is None else f'{value:.{digits}f}'
M=read('analysis/m4_confirmatory_summary.json'); HE=read('analysis/m4_humaneval_summary.json')['conditions']['fixed_k2']; R=read('reports/5070ti/windows_humaneval_summary.json')['summaries']; B=read('analysis/b570_exact_fallback_summary.json'); H=read('analysis/358h_phase3_summary.json')
for n,k in [('MRepSpeed','geomean_speedup'),('MRepN','prompt_count'),('MRepPairs','paired_repetitions'),('MRepExact','exact_pairs'),('MRepFaster','faster_prompts')]: val(n,M[k],3 if n=='MRepSpeed' else None)
val('MRepLo',M['bootstrap_95_ci'][0],3);val('MRepHi',M['bootstrap_95_ci'][1],3)
for n,k in [('MHEspeed','prompt_geomean_speedup'),('MHEprompts','prompt_count'),('MHEpairs','pair_count'),('MHEexact','exact_pairs'),('MHEfaster','faster_prompts')]:val(n,HE[k],3 if n=='MHEspeed' else None)
for n,v in [('MHElo',HE['prompt_bootstrap_95_ci'][0]),('MHEhi',HE['prompt_bootstrap_95_ci'][1]),('MHEenergy',HE['prompt_geomean_energy_efficiency_ratio']),('MHEenergyLo',HE['energy_bootstrap_95_ci'][0]),('MHEenergyHi',HE['energy_bootstrap_95_ci'][1])]:val(n,v,3)
for tag,s in zip(['RTXcpu','RTXgpu'],R):
 for n,k in [('Speed','geomean_speedup'),('Lo','ci95_low'),('Hi','ci95_high')]: val(tag+n,s[k],3)
val('RTXexact',R[0]['exact_pairs'])
for n,v in [('BSpeed',B['performance']['prompt_geometric_mean_speedup']),('BLo',B['performance']['bootstrap_95_ci'][0]),('BHi',B['performance']['bootstrap_95_ci'][1]),('BvShort',B['V2_exact']['512']),('BvLong',B['V2_exact']['2048'])]:val(n,v,4 if n in ['BSpeed','BLo','BHi'] else 3)
val('BExact',B['correctness']['exact_pairs']);val('BExactPrompts',B['correctness']['exact_prompts'])
# Exact-pair count independently read from the frozen diagnostic report's 30 rows.
brep=(ROOT/'reports/b570/B570_HUMANEVAL30_DIAGNOSTIC.md').read_text(); fast_exact=3*sum('NO_DIVERGENCE' in l for l in brep.splitlines());val('BFastExact',fast_exact)
ver=rows('reports/5070ti/WINDOWS_EXACT_VERIFICATION_COST.csv')
for n,row in zip(['RTXrawZero','RTXserZero','RTXrawDepth','RTXserDepth'],ver):val(n,float(row['T_verify2_over_T_decode1']),3)
val('HExact',H['correctness']['CPU']['exact_pairs'])
agg={}
for dev,tag in [('CPU','Hcpu'),('NPU','Hnpu')]:
 p=H['performance'][dev];a=H['acceptance'][dev];d=H['decomposition'][dev];c=a['mean_committed_tokens_per_round_C']
 for n,v in [('Speed',p['geometric_mean_speedup']),('Lo',p['bootstrap_ci95'][0]),('Hi',p['bootstrap_ci95'][1]),('C',c)]:val(tag+n,v,4 if n=='C' else 3)
 for n,k in [('Draft','draft_replay_plus_proposal'),('Target','target_verification'),('Residual','orchestration_residual')]:val(tag+n,d['fractions_of_speculative_time'][k]*100,2)
 rounds=a['total_speculative_rounds']; ntok=a['committed_output_tokens'];tb=d['baseline_end_to_end_ms']*90/ntok
 x={n:d[k]*90/rounds/tb for n,k in [('D','draft_replay_plus_proposal_ms'),('R','target_verification_ms'),('X','orchestration_residual_ms')]}
 x['C']=c;x['Aggregate']=d['baseline_end_to_end_ms']/d['speculative_end_to_end_ms'];agg[dev]=x
 assert abs(c/(x['D']+x['R']+x['X'])-x['Aggregate'])<1e-12
 for n in ['D','R','X','Aggregate']:val(tag+n,x[n],5 if n=='X' else 4)
write('tables/values.tex','% Generated from repository evidence by scripts/build_assets.py.\n'+''.join('\\newcommand{\\'+n+'}{'+v+'}\n' for n,v in mac.items()))
