record('M4-HE','M4','HumanEval primary speed, exactness, prompt count, package efficiency',HE,'Within-prompt GM of 3 paired ratios; prompt GM; Python Random 20260910; 100,000 draws; indices 2500,97499','90/90 token-exact','PRIMARY speed / SECONDARY energy','reports/m4/M4_HUMANEVAL_CODE_CONDITIONED.md','analysis/m4_humaneval_summary.json','scripts/summarize_m4_humaneval.py','artifacts/m4_humaneval_code_conditioned/results.json','Separate preregistration; no pass@k; package excludes DRAM; primary energy interval crosses one.')
