record('M4-SECONDARY','M4','Appendix registered p_min=0.9 energy; fixed k=2 secondary scope',sec,'Same frozen HumanEval estimator/bootstrap','90/90 token-exact','SECONDARY','reports/m4/M4_HUMANEVAL_CODE_CONDITIONED.md','analysis/m4_humaneval_summary.json','scripts/summarize_m4_humaneval.py','benchmarks/m4_code_conditioned_30q/preregistration.json','Not a replacement for fixed-k2; no material incremental speed claim.')
for s in R:
 record('RTX-'+s['condition'],'Core Ultra 9 275HX + RTX 5070 Ti Laptop','Serialized exact-control outcome and CI',s,'Within-prompt GM of 3 paired ratios; prompt GM; Python Random 20260910; 10,000 draws; indices 249,9749','90/90 token-exact','SECONDARY (historical report: exact diagnostic control)','reports/5070ti/HUMANEVAL_LLAMA_REPLICATION.md','reports/5070ti/HUMANEVAL_LLAMA_REPLICATION.csv','scripts/summarize_windows_humaneval_replication.py','artifacts/windows_humaneval_replication/manifest.json','Primary fast attempt correctness-blocked; weaker raw per-run provenance; no formal HumanEval energy claim.')
record('RTX-MICRO','RTX 5070 Ti Laptop','Path-specific target-forward ratios; depths 0/256; 20 repetitions',ver,'PP2 median / PP1 median; 20 observations per cell','Batched blocked; serialized exact on frozen full control','MECHANISM_SUPPORTED serialized / DIAGNOSTIC raw','reports/5070ti/WINDOWS_VERIFICATION_MECHANISM_CONTROLS.md','reports/5070ti/WINDOWS_EXACT_VERIFICATION_COST.csv','scripts/windows_exact_verification_microbench.py','artifacts/windows_verification_mechanism/manifest.json','Forward proxy is not full R_target.')
record('RTX-DIVERGENCE','RTX 5070 Ti Laptop','HumanEval/106: repeated 3/3; 2790 vs 2629; margin +0.080948 to -0.126457',read('reports/5070ti/CUDA_DIVERGENCE_LOGITS_SUMMARY.json'),'Captured score/token comparisons, not a population estimator','Batched divergence; baseline/serialized agree','MECHANISM_SUPPORTED','reports/5070ti/CUDA_DIVERGENCE_NUMERICAL_DIAGNOSIS.md','reports/5070ti/CUDA_DIVERGENCE_LOGITS_SUMMARY.json','scripts/debug/cuda_divergence/capture_logits_via_server.py','artifacts/windows_cuda_divergence/manifest.json','Same-commit instrumented diagnostic, distinct from formal binary; bounded case, no specific-kernel attribution.')
record('B570-FAST','Arc B570','45/90 fast-path exact pairs and fast V2 proxy',{'exact_pairs':fast_exact,'pairs':90,'prompts':30,'V2_512':1.2426,'V2_2048':1.6373},'Exactness count from diagnostic report; ratios of medians for microbenchmark','Correctness-blocked','DIAGNOSTIC','reports/b570/B570_HUMANEVAL30_DIAGNOSTIC.md','reports/b570/B570_VERIFICATION_MECHANISM.md','scripts/platform/b570/b570_verification_microbench.py','artifacts/b570_backend_control/diagnostic-v1-20260912-170834/manifest.json','Post-gate extension; fast micro values retained to report precision; never formal performance.')
record('B570-SERIAL','Arc B570','Serialized V2 proxy, speed CI, 60/90 exact, 20/30 exact prompts; appendix board energy',B,'Within-prompt GM; prompt GM; Python Random 20260910; 10,000 draws; indices 250,9750; original pair insertion order','60/90; global_admissible=false','DIAGNOSTIC','reports/b570/B570_EXACT_FALLBACK_VALIDATION.md','analysis/b570_exact_fallback_summary.json','scripts/platform/b570/finalize_b570_exact_fallback.py','artifacts/b570_backend_control/exact-fallback-v1-20260912-222617/exact_fallback/manifest.json','Legacy source field V2_exact is serialized in paper. Remote-contaminated earlier cells excluded. Energy board only.')
for dev in ['CPU','NPU']:
 record('358H-'+dev,'Core Ultra X7 358H '+dev,'Phase-3 outcome, direct C, decomposition and aggregate normalized accounting',{'performance':H['performance'][dev],'correctness':H['correctness'][dev],'acceptance':H['acceptance'][dev],'decomposition':H['decomposition'][dev],'aggregate_accounting':agg[dev]},'Within-prompt median of 3 ratios; prompt GM; NumPy default_rng 20260919; 10,000 draws; quantile(.025,.975). Decomposition is arithmetic totals/means, not prompt GM.','90/90 token-exact','PRIMARY outcomes / MECHANISM_SUPPORTED components','reports/358h/358H_PHASE3_END_TO_END_VALIDATION.md','analysis/358h_phase3_summary.json','scripts/platform/358h/analyze_phase3_campaign.py','artifacts/358h_threshold_validation/phase3-final-20260918-144458/manifest.json','Post-prefill; draft call includes full-prefix replay plus proposal; complete target-side region; no end-to-end energy; reconstructed source STRONGLY_SUPPORTED.')
isolated=rows('analysis/358h_draft_device_summary.csv')
record('358H-ISOLATED','Core Ultra X7 358H','Figure isolated CPU/NPU steady-state draft tok/s at contexts 512,2048,8192',isolated,'Five repetitions per context; median steady-state tokens/s, telemetry-OFF Track L','Isolated draft characterization, not E2E token equivalence','MECHANISM_SUPPORTED','reports/358h/358H_DRAFT_DEVICE_CHARACTERIZATION.md','analysis/358h_draft_device_summary.csv','scripts/platform/358h/process_phase1_phase2_results.py','analysis/358h_draft_device_summary.json','Steady-state excludes the large first-token/prefix cost; separate boundary from realized Phase 3.')
vm=rows('work/m4/llama_verify_q8_synced.csv'); mv=[]
for ctx in [512,2048,8192]:
 med={k:statistics.median(float(r['elapsed_us']) for r in vm if int(r['prefix_tokens'])==ctx and int(r['verify_tokens'])==k) for k in [1,2]};mv.append({'context':ctx,'ratio':med[2]/med[1]})
record('M4-MICRO','M4','Metal V2_micro at three contexts, approximately 1.02--1.08',mv,'Ratio of medians of seven synchronized target-forward observations per cell','Final full-workload native paths exact; proxy itself is a timing study','MECHANISM_SUPPORTED','reports/m4/M4_SPECULATION_MECHANISM_DIAGNOSIS.md','work/m4/llama_verify_q8_synced.csv','scripts/setup/macos/llama_verify_microbench.cpp','artifacts/m4_humaneval_code_conditioned/manifest.json','Historical causal prose superseded by handoff; not full R_target or unified-memory causality.')
