configs=[('M4-PROTOCOL','M4',{'systems_in_study':4,'target':'Qwen3-8B Q8_0','draft':'Qwen3-0.6B Q8_0','build':10809,'runtime_commit':'5266f24da','representative_prompts':24,'groups':6,'per_group':4,'HE_prompts':30,'HE_population':164,'repetitions':3,'HE_cap':128,'k':2},'reports/m4/M4_CONFIRMATORY_VALIDATION.md','benchmarks/m4_code_conditioned_30q/preregistration.json','scripts/m4_humaneval_code_conditioned.py','artifacts/m4_humaneval_code_conditioned/manifest.json'),('RTX-PROTOCOL','RTX 5070 Ti Laptop',{'target':'Qwen3-8B Q8_0','draft':'Qwen3-0.6B Q8_0','CPU':'Core Ultra 9 275HX','build':10839,'commit':'0cae43063','CUDA':'12.4','microbatch':[1,2],'repetitions':3,'cap':128,'prompts':30,'k':2},'reports/5070ti/HUMANEVAL_LLAMA_REPLICATION.md','benchmarks/windows_humaneval_replication_30q/manifest.json','scripts/windows_humaneval_llama_replication.py','artifacts/windows_humaneval_replication/manifest.json'),('B570-PROTOCOL','Arc B570',{'CPU':'Core i5-13400','target':'Qwen3-8B Q8_0','draft':'Qwen3-0.6B Q8_0','build':10839,'serialized_microbatch':1,'fast_microbatch':128,'probe_prompts':6,'probe_exact_pairs':'18/18','full_prompts':30,'repetitions':3,'cap':128,'k':2},'reports/b570/B570_ENVIRONMENT_QUALIFICATION.md','benchmarks/b570_backend_control/exact_fallback_validation_v1.json','scripts/platform/b570/b570_exact_fallback_validation.py','artifacts/b570_backend_control/exact-fallback-v1-20260912-222617/exact_fallback/manifest.json'),('358H-PROTOCOL','Core Ultra X7 358H',{'target':'Qwen3-8B Q8_0 Arc B390 Vulkan0','draft':'Qwen3-0.6B symmetric INT4 OpenVINO CPU/NPU','build':10839,'cap':128,'k':2,'prompts':30,'repetitions':3,'stage_A_exact_per_path':'18/18'},'reports/358h/358H_PHASE3_END_TO_END_VALIDATION.md','analysis/358h_phase3_summary.json','scripts/platform/358h/phase3_heterogeneous_runner.py','artifacts/358h_threshold_validation/phase3-final-20260918-144458/manifest.json')]
for id,platform,v,r,a,s,ar in configs:record(id,platform,'Methodology/table configuration and sample sizes',v,'Frozen settings/counts; not statistical estimates','As qualified by campaign','PROTOCOL',r,a,s,ar,'Hardware labels/model sizes are fixed identities; scope does not establish cross-stack equality.')
