lines=['# Manuscript Evidence Ledger','', 'Manuscript v0.1 — hardware-complete / runtime-reserved. Internal, not part of anonymous PDFs.','',f'Frozen repository baseline: `{BASE}`. Generated by `manuscript/scripts/build_assets.py`. Full-precision values and file SHA-256 hashes are also in `published_values.json`. Figures/tables use these sources; macros prevent manual headline transcription.','', 'All empirical quantitative claims in abstract, sections, captions, tables, figures and appendix map below. Numerical constants in equations are definitions; section/figure numbers, version labels and the 1.5–2-page planning allocation are not experiment results. Reference years/volumes/pages belong to the citation audit.','', '## Placement map','', '| Evidence | Manuscript locations |','|---|---|','| M4-24, M4-HE | Abstract; §§3,5; Figure 3; Table 3 |','| M4-MICRO, RTX-MICRO, B570-FAST, B570-SERIAL | §4; Figure 2; Table 2 |','| RTX-DIVERGENCE | §4 numerical capture |','| RTX-cpu_k2, RTX-rtx_k2 | §5; Table 3 |','| 358H-CPU, 358H-NPU | §5; Figures 4–5; Table 3; appendix accounting |','| 358H-ISOLATED | Figure 4 |','| *-PROTOCOL | §3; Table 1; appendix |','| M4-SECONDARY, M4-HE, B570-SERIAL | Appendix energy table |','', '## Claim records','']
for r in ledger:
 lines+=['### '+r['id'],'',f"- Manuscript claim: {r['manuscript_claim']}",f"- Platform: {r['platform']}",f"- Statistical estimator: {r['statistical_estimator']}",f"- Correctness status: {r['correctness_status']}",f"- Evidence class: {r['evidence_class']}",f"- Source report: `{r['source_report']}`",f"- Analysis file: `{r['analysis_file']}`",f"- Script: `{r['script']}`",f"- Archive: `{r['archive']}`",'- Source commits: '+ '; '.join(f'`{p}` → `{c}`' for p,c in r['source_commit'].items()),f"- Caveat: {r['caveat']}",'- Exact values:','```json',json.dumps(r['exact_value'],indent=2),'```','']
lines+=['## Non-numeric evidence and preserved deviations','','- Full-prefix semantics and complete target timing: `reports/358h/358H_RUNNER_SEMANTICS_MAPPING.md` and frozen `scripts/platform/358h/phase3_heterogeneous_runner.py`.','- Source reconstruction: `reports/358h/358H_PROVENANCE_AMENDMENT.md`, `reports/358h/358H_CANONICAL_DRAFT_RESOLUTION.md`; STRONGLY_SUPPORTED, not proven historical identity.','- M4 corrected synthetic ceiling NOT EXECUTED: handoff §6.1 and preregistration; earlier synthetic study cannot replace it.','- B570 formal stop: `reports/b570/B570_CORRECTNESS_GATE.md`; later diagnostics do not rescue the formal run.','- Energy boundaries: source reports above and handoff §§6,14. No common energy ranking.','- Historical MLX correctness history: `reports/m4/M4_CORRECTNESS_CHECK.md`; distinct from final Metal Q8_0 cells.','- Runtime section: proposed requirements/hypotheses only. No numerical result, simulation, forecast or implementation claim.','']
